/** s8 DoMysteryGiftYesNo(u8 *textState, u16 *windowId, bool8 yesNoBoxPlacement, const u8 *str) */
export function DoMysteryGiftYesNo(textState: any, windowId: any, yesNoBoxPlacement: any, str: any): any {
  let windowTemplate: any = null;
      let input: any = null;

      switch (textState)
      {
      case 0:
           
          StringExpandPlaceholders(gStringVar4, str);
          if (yesNoBoxPlacement == 0)
              windowId = AddWindow(sWindowTemplate_YesNoMsg_Wide);
          else
              windowId = AddWindow(sWindowTemplate_YesNoMsg);
          FillWindowPixelBuffer(windowId, _0x11);
          AddTextPrinterParameterized4(windowId, FONT_NORMAL, 0, 1, 0, 0, sMG_Ereader_TextColor_2, 0, gStringVar4);
          DrawTextBorderOuter(windowId, _0x001, 0x0F);
          CopyWindowToVram(windowId, COPYWIN_GFX);
          PutWindowTilemap(windowId);
          textState++;
          break;
      case 1:
           
          windowTemplate = sWindowTemplate_YesNoBox;
          if (yesNoBoxPlacement == 0)
              windowTemplate.tilemapTop = 9;
          else
              windowTemplate.tilemapTop = 15;
          CreateYesNoMenu(windowTemplate, 10, 14, 0);
          textState++;
          break;
      case 2:
           
          input = Menu_ProcessInputNoWrapClearOnChoose();
          if (input == MENU_B_PRESSED || input == 0 || input == 1)
          {
              textState = 0;
              rbox_fill_rectangle(windowId);
              ClearWindowTilemap(windowId);
              CopyWindowToVram(windowId, COPYWIN_MAP);
              RemoveWindow(windowId);
              return input;
          }
          break;
      case 0xFF:
          textState = 0;
          rbox_fill_rectangle(windowId);
          ClearWindowTilemap(windowId);
          CopyWindowToVram(windowId, COPYWIN_MAP);
          RemoveWindow(windowId);
          return MENU_B_PRESSED;
      }

      return MENU_NOTHING_CHOSEN;
}

